 row=dict(id=x['id'],fullOutputMeaningful=i in whole,fullOutputLoop=i in loops,intrusiveRepetition=i in loops|intrusive,reason=reasons[i],prefixAndTextSha256=hashlib.sha256(json.dumps(dict(prefix=x['prefix'],text=x['text']),ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest());rows.append(row)
